    private void jButton1MouseClicked(java.awt.event.MouseEvent evt) {//GEN-FIRST:event_jButton1MouseClicked
// TODO add your handling code here:
        if(username.getText().length()!=0 && Password.getText().length()!=0 &&
                Confirmpassword.getText().length()!=0 && Email.getText().length()!=0 && Tel.getText().length()!=0)
            if(Password.getText().equals(Confirmpassword.getText()))
            {
                InsertVideofile = new InsertDB(username.getText(),Password.getText(),Email.getText(),Tel.getText());
                JOptionPane.showMessageDialog(null,"User has been Update","User Update Complete",JOptionPane.PLAIN_MESSAGE);
                this.dispose();
            }else
            {
                JOptionPane.showMessageDialog(null,"Confirm Password wrong","Error Update User",JOptionPane.WARNING_MESSAGE);
            }
        else
        {
                JOptionPane.showMessageDialog(null,"Please Complete all Filed","Error Update User",JOptionPane.WARNING_MESSAGE);
        }
    }//GEN-LAST:event_jButton1MouseClicked

